def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    strong_prev_bids = []
    desperate_count = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev['bid']
                prev_bids.append(bid)
                if bid >= DAILY_SALARY * 0.9:
                    strong_prev_bids.append(bid)

    if budget <= 0:
        return 0

    if not alive_opponents:
        return min(budget, 18)

    guaranteed_units = int(supply // WATER_REQ)
    total_players = 1 + len(alive_opponents)
    scarcity = guaranteed_units < total_players

    highest_prev = max(prev_bids) if prev_bids else 0
    second_highest_prev = 0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_highest_prev = sorted_bids[int(1)]

    emergency = hp <= 2 or no_water_days >= 1
    caution = hp <= 4

    if emergency:
        if scarcity:
            target = max(92, highest_prev + 2)
        else:
            target = max(58, second_highest_prev * 0.75 + 3)
        return min(budget, target)

    if scarcity:
        if len(strong_prev_bids) >= max(1, guaranteed_units):
            target = 16
            if caution:
                target = 34
            if desperate_count >= guaranteed_units:
                target = 44
            return min(budget, target)
        target = max(48, highest_prev * 0.55 + 2)
        if caution:
            target = max(target, 62)
        return min(budget, target)

    target = 22
    if highest_prev <= 20:
        target = 24
    elif highest_prev >= 100:
        target = 18
    else:
        target = max(20, min(38, highest_prev * 0.35))

    if caution:
        target = max(target, 36)
    if desperate_count >= 2:
        target = max(target, 42)

    return min(budget, target)

