def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10 # Total days in the episode, from meta-round state

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_players = len(alive_opponents) + 1 # Me + alive opponents

    # Calculate how many players can get their water requirement
    num_water_units_available = int(current_supply // WATER_REQ)

    strong_competitor_bids_yesterday = []
    weak_competitor_bids_yesterday = []

    # Identify strong competitors (Alex, Bob) and filter by their current budget
    # A threshold for "low budget" to consider them less of a threat.
    LOW_BUDGET_THRESHOLD = DAILY_SALARY * 0.5 

    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev_trace = opp.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                if opp_id in ["Alex", "Bob"] and opp['budget'] >= LOW_BUDGET_THRESHOLD:
                    strong_competitor_bids_yesterday.append(prev_trace['bid'])
                else:
                    weak_competitor_bids_yesterday.append(prev_trace['bid'])

    highest_strong_bid = 0
    if strong_competitor_bids_yesterday:
        highest_strong_bid = max(strong_competitor_bids_yesterday)

    # Highest bid from any opponent (strong or weak) from yesterday
    highest_opponent_bid_yesterday = 0
    all_yesterday_bids = strong_competitor_bids_yesterday + weak_competitor_bids_yesterday
    if all_yesterday_bids:
        highest_opponent_bid_yesterday = max(all_yesterday_bids)

    # --- Bidding Logic ---

    # 1. Critical HP / Missed water: Bid very aggressively to ensure survival.
    if my_hp <= 1 or my_no_water_days >= 1:
        bid_amount = DAILY_SALARY * 1.2 # Base aggressive bid (20% above salary)
        if highest_opponent_bid_yesterday > 0:
            bid_amount = max(bid_amount, highest_opponent_bid_yesterday + 10) # Try to outbid highest known

        return min(my_budget, bid_amount)

    # 2. Abundant supply or low competition: Bid low to save money.
    # If available water units are enough for all alive players, or if there are no strong competitors.
    num_strong_competitors_currently_active = len([o for o in opponents_status.values() if o['alive'] and o['agent_id'] in ["Alex", "Bob"] and o['budget'] >= LOW_BUDGET_THRESHOLD])

    if num_water_units_available >= num_alive_players or num_strong_competitors_currently_active == 0:
        # If there are weak competitors, bid slightly above their highest yesterday bid to ensure win
        if weak_competitor_bids_yesterday:
            return min(my_budget, max(DAILY_SALARY * 0.2, max(weak_competitor_bids_yesterday) + 1))
        return min(my_budget, DAILY_SALARY * 0.25) # Default low bid to save budget

    # 3. Competitive scenario: Fewer water units than players, and strong competitors are active.

    # If my HP is good, I can afford to be slightly less aggressive.
    if my_hp > 5: 
        bid_amount = DAILY_SALARY * 0.8 # Solid bid
        if highest_strong_bid > 0:
            bid_amount = max(bid_amount, highest_strong_bid + 2) # Try to slightly beat the highest strong bid
        return min(my_budget, bid_amount)

    # If my HP is moderate, I need water more urgently.
    else: # my_hp is 2, 3, 4, 5
        bid_amount = DAILY_SALARY * 0.95 # Strong and urgent bid
        if highest_strong_bid > 0:
            bid_amount = max(bid_amount, highest_strong_bid + 5) # Try to beat the highest strong bid more decisively
        return min(my_budget, bid_amount)

    # Fallback (should not be reached under normal conditions)
    return min(my_budget, DAILY_SALARY * 0.6)
